31 |         JSON.parse(potentiallyMalformedJson);
32 |         return potentiallyMalformedJson;
33 |     } catch (e) {
34 |         originalError.push({ message: e instanceof Error ? e.message : String(e) });
35 |     }
36 | 
37 |     // 使用 json5 解析更宽松的 JSON
38 |     try {
39 |         const parsed = parseJson5(potentiallyMalformedJson);
40 |         return JSON.stringify(parsed);
41 |     } catch (e) {
42 |         originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 1 });
43 |     }
44 | 
45 |     // 只有在 json5 失败后才执行复杂的修复逻辑
46 |     let fixed = potentiallyMalformedJson;
47 |     
48 |     // 检查最常见的截断问题
49 |     const openBraces = (fixed.match(/{/g) || []).length;
50 |     const closeBraces = (fixed.match(/}/g) || []).length;
51 |     const openBrackets = (fixed.match(/\[/g) || []).length;
52 |     const closeBrackets = (fixed.match(/\]/g) || []).length;
53 | 
54 |     if (openBraces > closeBraces || openBrackets > closeBrackets) {
55 |         const braceDiff = openBraces - closeBraces;
56 |         const bracketDiff = openBrackets - closeBrackets;
57 |         fixed += '}'.repeat(braceDiff) + ']'.repeat(bracketDiff);
58 |         
59 |         try {
60 |             JSON.parse(fixed);
61 |             return fixed;
62 |         } catch (e) {
63 |             originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 2 });
64 |         }
65 |     }
66 | 
67 |     // 最后的尝试
68 |     const fixed2 = attemptToCloseJson(fixed);
69 |     try {
70 |         JSON.parse(fixed2);
71 |         return fixed2;
72 |     } catch (e) {
73 |         originalError.push({ message: e instanceof Error ? e.message : String(e), attempt: 3 });
74 |     }
75 | 
76 |     throw new Error(`Failed to fix malformed JSON. Original errors: ${JSON.stringify(originalError)}`);
77 | }
