81 | /**
82 |  * 尝试通过智能闭合来修复 JSON
83 |  */
84 | function attemptToCloseJson(json: string): string {
85 |   let result = json.trim();
86 | 
87 |   // 移除末尾可能的未完成部分
88 |   // 如果最后一个字符是逗号，移除它
89 |   if (result.endsWith(',')) {
90 |     result = result.slice(0, -1);
91 |   }
92 | 
93 |   // 统计括号
94 |   const counts = countBraces(result);
95 | 
96 |   // 如果缺少闭合引号，添加
97 |   if (counts.openQuotes % 2 !== 0) {
98 |     result = result + '"';
99 |   }
100 | 
101 |   // 闭合括号
102 |   for (let i = 0; i < counts.openBraces - counts.closeBraces; i++) {
103 |     result = result + '}';
104 |   }
105 |   for (let i = 0; i < counts.openBrackets - counts.closeBrackets; i++) {
106 |     result = result + ']';
107 |   }
108 | 
109 |   return result;
110 | }
111 | 
112 | /**
113 |  * 统计 JSON 中的括号和引号
114 |  */
115 | function countBraces(json: string) {
116 |   const counts = {
117 |     openBraces: 0,
118 |     closeBraces: 0,
119 |     openBrackets: 0,
120 |     closeBrackets: 0,
121 |     openQuotes: 0,
122 |   };
123 | 
124 |   let inString = false;
125 |   let escapeNext = false;
126 | 
127 |   for (const char of json) {
128 |     if (escapeNext) {
129 |       escapeNext = false;
130 |       continue;
131 |     }
132 | 
133 |     if (char === '\\') {
134 |       escapeNext = true;
135 |       continue;
136 |     }
137 | 
138 |     if (char === '"') {
139 |       if (!inString) {
140 |         counts.openQuotes++;
141 |         inString = true;
142 |       } else {
143 |         counts.openQuotes++; // 计数，不区分开闭
144 |         inString = false;
145 |       }
146 |       continue;
147 |     }
148 | 
149 |     if (!inString) {
150 |       if (char === '{') counts.openBraces++;
151 |       if (char === '}') counts.closeBraces++;
152 |       if (char === '[') counts.openBrackets++;
153 |       if (char === ']') counts.closeBrackets++;
154 |     }
155 |   }
156 | 
157 |   return counts;
158 | }
