223 |   async generate(messages: Message[], options?: LLMOptions): Promise<LLMResponse | null> {
224 |     const { model, max_tokens, temperature, tools } = options || {}
225 |     const MAX_CONTINUE_ROUNDS = 2; // 最多续写 2 次
226 | 
227 |     let accumulatedContent = '';
