241 |     const cleanMessage = (msg: Message) => {
242 |       const cleaned: Record<string, unknown> = {
243 |         role: msg.role,
244 |         content: msg.content
245 |       };
246 |       // 保留 tool_call_id（tool 回复必需）
247 |       if (msg.tool_call_id) {
248 |         cleaned.tool_call_id = msg.tool_call_id;
249 |       }
250 |       // 保留 tool_calls（assistant 调用工具必需）
251 |       if (msg.tool_calls) {
252 |         cleaned.tool_calls = msg.tool_calls;
253 |       }
254 |       return cleaned;
255 |     };
256 | 
257 |     let currentMessages = messages.map(cleanMessage);
258 |     let continueRound = 0;
259 | 
260 |     while (continueRound <= MAX_CONTINUE_ROUNDS) {
261 |       try {
262 |         const requestBody: Record<string, unknown> = {
263 |           model: model || this.model,
264 |           messages: currentMessages,
265 |           max_tokens: max_tokens || this.maxOutputTokens,
266 |           temperature: temperature || 0.1,
267 |         };
268 | 
269 |         // 添加 tools 参数（如果提供）
270 |         if (tools && tools.length > 0) {
271 |           requestBody.tools = tools;
272 |         } 
273 |        fs.writeFileSync('./openai-request.json', JSON.stringify(requestBody, null, 2));
274 |         const response = await fetch(`${this.baseURL}/chat/completions`, {
275 |           method: 'POST',
276 |           headers: {
277 |             'Content-Type': 'application/json',
278 |             'Authorization': `Bearer ${this.config.apiKey}`,
279 |           },
280 |           body: JSON.stringify(requestBody),
281 |         });
282 | 
283 |         if (!response.ok) {
284 |           const errorBody = await response.text();
285 |           console.error('API Error Response:', errorBody);
286 |           throw new Error(`API request failed: ${response.status} ${response.statusText}\n${errorBody}`);
287 |         }
288 | 
289 |         const data = await response.json() as ChatCompletionResponse;
290 |         const finishReason = data.choices[0]?.finish_reason;
291 | 
292 |         // 累加使用量
293 |         if (data.usage) {
294 |           totalUsage.prompt_tokens += data.usage.prompt_tokens;
295 |           totalUsage.completion_tokens += data.usage.completion_tokens;
296 |           totalUsage.total_tokens += data.usage.total_tokens;
297 |         }
298 | 
299 |         const messageContent = data.choices[0]?.message?.content || '';
300 |         const messageToolCalls = data.choices[0]?.message?.tool_calls || [];
301 | 
302 |         // 尝试修复 tool_calls 中可能格式错误的 arguments
303 |         const fixedToolCalls = messageToolCalls.map(tc => ({
304 |           ...tc,
305 |           function: {
306 |             ...tc.function,
307 |             arguments: fixMalformedJson(tc.function.arguments),
308 |           },
309 |         }));
310 | 
311 |         // 累加内容
312 |         if (continueRound === 0) {
313 |           accumulatedContent = messageContent;
314 |           accumulatedToolCalls = fixedToolCalls;
315 |         } else {
316 |           // 续写时追加内容
317 |           accumulatedContent += messageContent;
318 |           // 续写时可能需要合并 tool_calls
319 |           if (fixedToolCalls.length > 0) {
320 |             accumulatedToolCalls = fixedToolCalls;
321 |           }
322 |         }
323 | 
324 |         // 检查是否需要续写
325 |         if (finishReason === 'length' && continueRound < MAX_CONTINUE_ROUNDS) {
326 |           // 需要续写
327 |           continueRound++;
328 | 
329 |           // 构建续写消息：将当前部分响应作为 assistant 消息添加
330 |           currentMessages = [
331 |             ...currentMessages,
332 |             {
333 |               role: 'assistant' as const,
334 |               content: accumulatedContent,
335 |               tool_calls: messageToolCalls, // 使用原始的 tool_calls 用于续写
336 |             },
337 |           ];
338 | 
339 |           console.log(`[OpenAIProvider] Response truncated, continuing... (round ${continueRound}/${MAX_CONTINUE_ROUNDS})`);
340 |           continue;
