343 |         // 正常返回
344 |         return {
345 |           content: accumulatedContent,
346 |           role: 'assistant',
347 |           type: data.choices[0]?.message?.type || 'text',
348 |           tool_calls: accumulatedToolCalls,
349 |           usage: totalUsage,
350 |           finishReason,
351 |         };
352 | 
353 |       } catch (error) {
