      fs.writeFileSync(TEST_FILE, 'café\nnaïve\nstraße', 'utf-8');
      const tool = createTool();

      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 1,
        oldText: 'café',
        newText: 'restaurant',
