        oldText: 'text',
        newText: 'newText',
      });

      expect(result).toContain('Error: File not found');
    });

    it('应该处理相对路径的文件不存在', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: './non-existent-dir/file.txt',
        line: 1,
        oldText: 'text',
        newText: 'newText',
      });

      expect(result).toContain('Error: File not found');
    });
  });

  describe('错误处理 - 行号越界', () => {
    it('应该返回行号小于1的错误', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 0,
        oldText: 'line1',
        newText: 'newText',
      });

      expect(result).toContain('Error: Line number out of range');
    });

    it('应该返回行号为负数的错误', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: -1,
        oldText: 'line1',
        newText: 'newText',
      });

      expect(result).toContain('Error: Line number out of range');
    });

    it('应该返回行号大于总行数的错误', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 100,
        oldText: 'line1',
        newText: 'newText',
      });

      expect(result).toContain('Error: Line number out of range');
    });

    it('应该返回行号恰好等于总行数+1的错误', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 6,
        oldText: 'line1',
        newText: 'newText',
      });

      expect(result).toContain('Error: Line number out of range');
    });
  });

  describe('错误处理 - oldText 不匹配', () => {
    it('应该返回 oldText 不存在的错误', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 2,
        oldText: 'non-existent-text',
        newText: 'newText',
      });

      expect(result).toContain('not found on line 2');
      expect(result).toContain('content is: "line2"');
    });

    it('应该返回大小写不匹配的错误（区分大小写）', async () => {
      const tool = createTool();
      const result = await tool.execute({
        filePath: TEST_FILE,
        line: 2,
        oldText: 'LINE2', // 大写，实际是小写
        newText: 'newText',
