        filePath: path.join(TEST_DIR, 'non-existent-file.txt'),
        line: 1,
        oldText: 'text',
        newText: 'newText',
      });

      expect(result).toContain('Error: File not found');
    });

    it('应该处理相对路径的文件不存在', async () => {
